//@version=6
// ============================================================================
// Wave Navigator [WavesUnchained]
// Version: 2.0
// Author: WavesUnchained
// Build: 2025-10-13 02:06:31
// ============================================================================
// Multi-timeframe Elliott Wave detector using ZigZag swings, rule engine, weighted scoring, and persistent visualization
//
// Features:
//   ✓ ZigZag-based pivot detection
//   ✓ Elliott Wave pattern detection (Impulse, Diagonal, Flat, Triangle)
//   ✓ Rule engine with Elliott validation
//   ✓ Advanced scoring system (Momentum, Volume, Time ratio)
//   ✓ Persistent visualization (LuxAlgo-style dynamic updates)
//   ✓ Multi-pattern ranking (Top-N display)
//   ✓ RSI/MACD momentum confirmation
//   ✓ Volume-based wave strength validation
//   ✓ Fibonacci retracement/extension zones
//   ✓ Real-time pattern table with score breakdown
//
// ⚠️  AUTO-GENERATED - DO NOT EDIT MANUALLY!
// Generated by build.py from modules in wave-navigator/
// ============================================================================

//@version=6
indicator("Wave Navigator [WavesUnchained]", shorttitle="WN", overlay=true, max_labels_count=500, max_lines_count=500, max_boxes_count=500)

// ============================================================================
// SHARED MODULES
// ============================================================================

// ===== SHARED: HELPERS =====
// ============================================================================
// SHARED HELPERS - Universal Utility Functions (SHARED MODULE)
// ============================================================================
// @version=6
// @description: Common utility functions shared across indicators
//
// Purpose:
//   ✓ Math utilities (normalization, clamping, etc.)
//   ✓ Pivot detection
//   ✓ Zone calculations
//   ✓ Array utilities
//
// Used by: CPM, ZigZag Corridors, Pattern Pilot, Wave Analysis
//
// Integration:
//   Reference in config.json: "../_shared/helpers.pine"
//
// Note: Indicator-specific logic should remain in local modules.
//       Only truly generic utilities belong here.
// ============================================================================

// ==== MATH UTILITIES ====

// Calculate z-score (standardization)
// @param src: Source series
// @param len: Lookback period
// @returns Z-score
f_zscore(float src, int len) =>
    float ma = ta.sma(src, len)
    float sd = ta.stdev(src, len)
    sd == 0.0 ? 0.0 : (src - ma) / sd

// Map value to signed range [-1, +1]
// @param x: Input value
// @param lo: Lower bound
// @param hi: Upper bound
// @returns Normalized value in [-1, +1]
f_signed(float x, float lo, float hi) =>
    float cl = math.max(lo, math.min(hi, x))
    (cl - lo) / (hi - lo) * 2.0 - 1.0

// Clamp value to range
// @param x: Input value
// @param min: Minimum value
// @param max: Maximum value
// @returns Clamped value
f_clamp(float x, float min, float max) =>
    math.max(min, math.min(max, x))

// Normalize value to [0, 1] range
// @param x: Input value
// @param lo: Lower bound
// @param hi: Upper bound
// @returns Normalized value in [0, 1]
f_normalize(float x, float lo, float hi) =>
    float rangeVal = hi - lo
    rangeVal == 0.0 ? 0.5 : (x - lo) / rangeVal

// Safe division (avoid divide by zero)
// @param numerator: Numerator
// @param denominator: Denominator
// @param defaultVal: Value to return if denominator is zero
// @returns Division result or default
f_safeDivide(float numerator, float denominator, float defaultVal = 0.0) =>
    denominator == 0.0 ? defaultVal : numerator / denominator

// ==== PIVOT DETECTION ====

// Generic pivot high detection
// @param src: Source series (typically high)
// @param leftBars: Bars to left of pivot
// @param rightBars: Bars to right of pivot
// @returns Pivot high price or na
pivotHigh(series float src, int leftBars, int rightBars) =>
    ta.pivothigh(src, leftBars, rightBars)

// Generic pivot low detection
// @param src: Source series (typically low)
// @param leftBars: Bars to left of pivot
// @param rightBars: Bars to right of pivot
// @returns Pivot low price or na
pivotLow(series float src, int leftBars, int rightBars) =>
    ta.pivotlow(src, leftBars, rightBars)

// Get last confirmed pivot (with index)
// @param src: Source series
// @param leftBars: Bars to left
// @param rightBars: Bars to right
// @param isHigh: True for pivot high, False for pivot low
// @returns [pivotPrice, pivotIndex]
f_lastPivot(series float src, int leftBars, int rightBars, bool isHigh) =>
    var float lastVal = na
    var int lastIdx = na

    if isHigh
        float ph = pivotHigh(src, leftBars, rightBars)
        if not na(ph)
            lastVal := ph
            lastIdx := bar_index - rightBars
    else
        float pl = pivotLow(src, leftBars, rightBars)
        if not na(pl)
            lastVal := pl
            lastIdx := bar_index - rightBars

    [lastVal, lastIdx]

// ==== ZONE UTILITIES ====

// Calculate overlap percentage between two zones
// @param aLo: Zone A lower bound
// @param aHi: Zone A upper bound
// @param bLo: Zone B lower bound
// @param bHi: Zone B upper bound
// @returns Overlap percentage (0-100)
f_overlap(float aLo, float aHi, float bLo, float bHi) =>
    float lo = math.max(aLo, bLo)
    float hi = math.min(aHi, bHi)
    float inter = math.max(0.0, hi - lo)
    float base = math.max(aHi - aLo, bHi - bLo)
    base > 0 ? inter / base * 100.0 : 0.0

// Calculate proximity to level (ATR-normalized)
// @param price: Current price
// @param level: Target level
// @param atr: ATR value
// @returns Distance in ATR units
f_proximity(float price, float level, float atr) =>
    atr > 0 ? math.abs(price - level) / atr : 10.0

// Check if price is within zone
// @param price: Price to check
// @param zoneLo: Zone lower bound
// @param zoneHi: Zone upper bound
// @returns True if price in zone
f_inZone(float price, float zoneLo, float zoneHi) =>
    price >= zoneLo and price <= zoneHi

// ==== OSCILLATOR UTILITIES ====

// RSI z-score
// @param len: RSI length
// @param zscore_len: Z-score lookback
// @returns RSI z-score
f_rsi_zscore(int len, int zscore_len) =>
    float rsi = ta.rsi(close, len)
    f_zscore(rsi, zscore_len)

// ==== ARRAY UTILITIES ====

// Safe array get with default value
// @param arr: Float array
// @param idx: Index
// @param defaultVal: Default if index invalid
// @returns Array value or default
f_get_float(array<float> arr, int idx, float defaultVal) =>
    idx >= 0 and idx < array.size(arr) ? array.get(arr, idx) : defaultVal

// Safe array get with default value (int)
// @param arr: Int array
// @param idx: Index
// @param defaultVal: Default if index invalid
// @returns Array value or default
f_get_int(array<int> arr, int idx, int defaultVal) =>
    idx >= 0 and idx < array.size(arr) ? array.get(arr, idx) : defaultVal

// ==== TIMEFRAME UTILITIES ====

// Check if current bar is start of new session
// @returns True if new session started
f_isNewSession() =>
    ta.change(time("D"))

// Check if current bar is start of new week
// @returns True if new week started
f_isNewWeek() =>
    ta.change(time("W"))

// Check if current bar is start of new month
// @returns True if new month started
f_isNewMonth() =>
    ta.change(time("M"))

// ==== VOLATILITY UTILITIES ====

// (Volatility functions moved to _shared/indicators.pine)

// ==== TREND UTILITIES ====

// Calculate simple slope
// @param src: Source series
// @param len: Lookback length
// @returns Slope (change per bar)
f_slope(series float src, int len) =>
    (src - src[len]) / len

// Check if series is rising
// @param src: Source series
// @param len: Lookback length
// @returns True if rising
f_isRising(series float src, int len) =>
    ta.rising(src, len)

// Check if series is falling
// @param src: Source series
// @param len: Lookback length
// @returns True if falling
f_isFalling(series float src, int len) =>
    ta.falling(src, len)

// ==== VOLUME UTILITIES ====

// Volume strength score (0-1 scale)
// @param length: Volume MA period
// @returns Strength score based on volume ratio
f_volumeStrength(int length = 20) =>
    float volMA = ta.sma(volume, length)
    float ratio = volMA > 0 ? volume / volMA : 1.0
    // 0.0 = below 50% of MA, 0.5 = at MA, 1.0 = 2x MA or more
    math.min(ratio / 2.0, 1.0)

// Volume confirmation check
// @param length: Volume MA period
// @param threshold: Minimum ratio threshold (default 1.5x MA)
// @returns Boolean confirmation
f_volumeConfirmation(int length = 20, float threshold = 1.5) =>
    float volMA = ta.sma(volume, length)
    float ratio = volMA > 0 ? volume / volMA : 1.0
    ratio >= threshold

// Relative volume compared to specific bars
// @param barsAgo: Bars to compare to
// @returns Volume ratio vs previous bar
f_volumeRelative(int barsAgo = 1) =>
    float prevVol = nz(volume[barsAgo], volume)
    prevVol > 0 ? volume / prevVol : 1.0

// Volume spike detection
// @param length: Volume MA period
// @param spikeMultiplier: Multiplier for spike (default 2.0)
// @returns True if volume spike detected
f_volumeSpike(int length = 20, float spikeMultiplier = 2.0) =>
    float volMA = ta.sma(volume, length)
    float ratio = volMA > 0 ? volume / volMA : 1.0
    ratio >= spikeMultiplier

// Average volume over period
// @param length: Period length
// @returns Average volume
f_volumeAvg(int length = 20) =>
    ta.sma(volume, length)

// ==== MOMENTUM UTILITIES ====

// Get momentum at historical bar
// @param momentumSeries: Momentum series (RSI, MACD, etc.)
// @param barsAgo: Bars back to check
// @returns Momentum value at that bar
f_momentumAtBar(series float momentumSeries, int barsAgo) =>
    barsAgo >= 0 ? momentumSeries[barsAgo] : na

// Check momentum directional confirmation
// @param momentum1: First momentum value (earlier)
// @param momentum2: Second momentum value (recent)
// @param direction: Expected direction ("UP" or "DOWN")
// @param momentumType: Type ("RSI", "MACD")
// @returns Confirmation score (0-100)
f_momentumConfirmation(float momentum1, float momentum2, string direction, string momentumType = "RSI") =>
    float score = 50.0  // Neutral

    if not na(momentum1) and not na(momentum2)
        if direction == "UP"
            if momentumType == "RSI"
                // RSI should be increasing and above 50
                score := (momentum2 > momentum1 and momentum2 > 50) ? 100.0 : 
                         (momentum2 > momentum1) ? 75.0 : 
                         (momentum2 > 50) ? 60.0 : 40.0
            else if momentumType == "MACD"
                // MACD should be increasing and positive
                score := (momentum2 > momentum1 and momentum2 > 0) ? 100.0 : 
                         (momentum2 > momentum1) ? 75.0 : 
                         (momentum2 > 0) ? 60.0 : 40.0
        else if direction == "DOWN"
            if momentumType == "RSI"
                // RSI should be decreasing and below 50
                score := (momentum2 < momentum1 and momentum2 < 50) ? 100.0 : 
                         (momentum2 < momentum1) ? 75.0 : 
                         (momentum2 < 50) ? 60.0 : 40.0
            else if momentumType == "MACD"
                // MACD should be decreasing and negative
                score := (momentum2 < momentum1 and momentum2 < 0) ? 100.0 : 
                         (momentum2 < momentum1) ? 75.0 : 
                         (momentum2 < 0) ? 60.0 : 40.0

    score

// Check momentum divergence from price
// @param priceChange: Price change (positive or negative)
// @param momentumChange: Momentum change
// @returns [isDivergent, strength]
f_momentumDivergence(float priceChange, float momentumChange) =>
    bool isDivergent = (priceChange > 0 and momentumChange < 0) or 
                       (priceChange < 0 and momentumChange > 0)
    float strength = isDivergent ? math.abs(priceChange - momentumChange) : 0.0
    [isDivergent, strength]

// Calculate momentum strength score
// @param momentum: Current momentum value
// @param momentumType: Type ("RSI", "MACD")
// @returns Strength score (0-1)
f_momentumStrength(float momentum, string momentumType = "RSI") =>
    float strength = 0.5  // Neutral

    if momentumType == "RSI"
        // RSI 0-100 -> normalize to 0-1
        strength := momentum / 100.0
    else if momentumType == "MACD"
        // MACD is unbounded, use normalization
        strength := na(momentum) ? 0.5 : math.min(math.abs(momentum) / 10.0, 1.0)

    strength

// ==== PRICE ACTION UTILITIES ====

// Check if current bar is bullish
// @returns True if close > open
f_isBullBar() =>
    close > open

// Check if current bar is bearish
// @returns True if close < open
f_isBearBar() =>
    close < open

// Calculate bar body size
// @returns Absolute body size
f_bodySize() =>
    math.abs(close - open)

// Calculate upper wick size
// @returns Upper wick size
f_upperWick() =>
    high - math.max(open, close)

// Calculate lower wick size
// @returns Lower wick size
f_lowerWick() =>
    math.min(open, close) - low

// Body as percentage of total range
// @returns Body percentage (0-1)
f_bodyRatio() =>
    float rangeVal = high - low
    rangeVal > 0 ? f_bodySize() / rangeVal : 0.0

// ============================================================================
// END OF SHARED HELPERS MODULE
// ============================================================================
// Available Functions:
//   Math: f_zscore, f_signed, f_clamp, f_normalize, f_safeDivide
//   Pivots: pivotHigh, pivotLow, f_lastPivot
//   Zones: f_overlap, f_proximity, f_inZone
//   Oscillators: f_rsi_zscore
//   Arrays: f_get_float, f_get_int
//   Timeframe: f_isNewSession, f_isNewWeek, f_isNewMonth
//   Volatility: (moved to indicators.pine)
//   Trend: f_slope, f_isRising, f_isFalling
//   Volume: f_volumeStrength, f_volumeConfirmation,
//           f_volumeRelative, f_volumeSpike, f_volumeAvg
//   Momentum: f_momentumAtBar, f_momentumConfirmation, f_momentumDivergence,
//             f_momentumStrength
//   Price Action: f_isBullBar, f_isBearBar, f_bodySize, f_upperWick, 
//                 f_lowerWick, f_bodyRatio
//
// Usage Example:
//   // Z-score normalization
//   float rsiZ = f_zscore(ta.rsi(close, 14), 20)
//
//   // Pivot detection
//   [pivotPrice, pivotBar] = f_lastPivot(high, 5, 5, true)
//
//   // Zone overlap
//   float overlap = f_overlap(1.2000, 1.2050, 1.2030, 1.2080)  // 40%
// ============================================================================

// ===== SHARED: TYPES =====
// ============================================================================
// SHARED TYPES - Generic Data Structures (SHARED MODULE)
// ============================================================================
// @version=6
// @description: Common type definitions shared across indicators
//
// Purpose:
//   ✓ Define generic, reusable data structures
//   ✓ Ensure consistency across indicators
//   ✓ Reduce duplicate type definitions
//
// Used by: CPM, ZigZag Corridors, Pattern Pilot, Wave Analysis
//
// Integration:
//   Reference in config.json: "../_shared/types.pine"
//
// Note: Indicator-specific types should remain in local modules.
//       Only truly generic types belong here.
// ============================================================================

// ==== TF BLOCK (CPM/ZZC Multi-Timeframe Scoring) ====
// Timeframe analysis block for CPM-style multi-category scoring
// Used by: CPM, ZZC (multi-TF mode), any MTF dashboard
type TFBlock
    float scoreFlow       // Money flow score (-3 to +3)
    float scoreMom        // Momentum score (-3 to +3)
    float scoreTrend      // Trend score (-3 to +3)
    float scoreVol        // Volatility score (negative = high risk)
    float scoreStruct     // Market structure score
    float scoreDiv        // Divergence score
    float scoreTotal      // Weighted total score
    bool divUp            // Bullish divergence detected
    bool divDn            // Bearish divergence detected
    string badge          // Special condition badges (OB/OS/Div/etc)

// ==== SCORE BLOCK (Generic Scoring Container) ====
// Generic score block for any multi-factor scoring system
// Can be used for: TF analysis, feature scoring, signal strength, etc.
type ScoreBlock
    float score1        // Factor 1 score
    float score2        // Factor 2 score
    float score3        // Factor 3 score
    float score4        // Factor 4 score
    float score5        // Factor 5 score
    float score6        // Factor 6 score
    float scoreTotal    // Weighted total
    bool flagUp         // Bullish flag (divergence, pattern, etc.)
    bool flagDn         // Bearish flag
    string badge        // Status badge (OB/OS/Div/Strong/Weak/etc.)

// ==== ZONE (Generic Zone Definition) ====
// Generic zone/level definition for support, resistance, reversal zones, etc.
type Zone
    float upper         // Upper boundary
    float lower         // Lower boundary
    float center        // Center/pivot level
    int startBar        // Bar where zone begins
    int endBar          // Bar where zone ends (or na for ongoing)
    bool isActive       // Is zone currently active
    string zoneType     // Type: "support", "resistance", "reversal", "consolidation"
    color zoneColor     // Visualization color
    int touchCount      // Number of times zone was tested

// ==== LEG INFO (Generic Trend Leg) ====
// Generic trend leg/swing information
// Can represent: ZigZag leg, Elliott wave leg, trend swing, etc.
type LegInfo
    int startIdx        // Starting bar index
    float startPrice    // Starting price
    int endIdx          // Ending bar index
    float endPrice      // Ending price
    bool isUp           // True = upward leg, False = downward leg
    float moveAbs       // Absolute move (points)
    float movePct       // Percentage move
    int duration        // Bars in leg
    float avgSlope      // Average slope
    bool isValid        // Validation flag

// ==== SIGNAL METADATA (Generic Signal Container) ====
// Generic signal metadata for any signal system
type SignalMeta
    int signalType      // Signal type (e.g., -2 to +2, or custom enum)
    float confidence    // Confidence level (0-100%)
    float strength      // Signal strength score
    string direction    // "BULL", "BEAR", "NEUTRAL"
    string quality      // "STRONG", "MODERATE", "WEAK"
    bool isValid        // Validation flag
    int barIndex        // Bar where signal generated
    string reason       // Reason/description

// ==== PIVOT POINT (Price Pivot) ====
// Generic pivot point (high/low)
// Used by: ZZC, Pattern Pilot, Wave Pilot
type Pivot
    int barIndex        // Bar index of pivot
    float price         // Pivot price level
    bool isHigh         // True = pivot high, False = pivot low

// Extended pivot with strength
type PivotPoint
    int barIndex        // Bar index of pivot
    float price         // Pivot price level
    bool isHigh         // True = pivot high, False = pivot low
    float strength      // Pivot strength (optional, 0-1)
    bool isConfirmed    // Is pivot confirmed (past lookback period)

// ==== ENVELOPE STATE (Channel/Band State) ====
// Generic envelope/channel state
// Works for: Keltner, Bollinger, Donchian, ATR bands, etc.
type EnvelopeState
    float upper         // Upper band
    float lower         // Lower band
    float basis         // Middle/basis line
    float width         // Band width (absolute)
    float widthPct      // Band width (percentage of price)
    bool isExpanded     // Is envelope expanded (volatility high)
    bool isCompressed   // Is envelope compressed (volatility low)
    string envelopeType // Type: "KC", "BB", "DC", "ATR"

// ==== DIVERGENCE INFO ====
// Generic divergence information
type DivergenceInfo
    bool isBullish      // Bullish divergence (price LL, osc HL)
    bool isBearish      // Bearish divergence (price HH, osc LH)
    bool isHidden       // Hidden divergence (trend continuation)
    bool isRegular      // Regular divergence (trend reversal)
    float strength      // Divergence strength (0-1)
    int pivotBar        // Bar where divergence pivot occurred
    string oscillator   // Oscillator used: "RSI", "MACD", "MFI", etc.

// ==== MARKET STATE ====
// Generic market state/regime information
type MarketState
    string trend        // "UPTREND", "DOWNTREND", "SIDEWAYS"
    string phase        // "EXPANSION", "CONSOLIDATION", "REVERSAL"
    float volatility    // Volatility measure (ATR%, IV, etc.)
    float momentum      // Momentum measure (RSI, ROC, etc.)
    bool isTrending     // ADX-based trending flag
    bool isOverextended // Overbought/oversold flag
    string timeframe    // Timeframe of this state

// ============================================================================
// END OF SHARED TYPES MODULE
// ============================================================================
// Available Types:
//   ✓ ScoreBlock: Multi-factor scoring (10 fields)
//   ✓ Zone: Generic zone/level (9 fields)
//   ✓ LegInfo: Trend leg/swing (10 fields)
//   ✓ SignalMeta: Signal metadata (8 fields)
//   ✓ PivotPoint: Price pivot (5 fields)
//   ✓ EnvelopeState: Channel/band state (8 fields)
//   ✓ DivergenceInfo: Divergence information (7 fields)
//   ✓ MarketState: Market regime (7 fields)
//
// Usage Example:
//   // Create a zone
//   Zone supZone = Zone.new()
//   supZone.upper := 1.2050
//   supZone.lower := 1.2000
//   supZone.zoneType := "support"
//
//   // Create signal metadata
//   SignalMeta sig = SignalMeta.new()
//   sig.signalType := 2  // Strong bull
//   sig.confidence := 85.0
//   sig.direction := "BULL"
// ============================================================================

// ===== SHARED: INDICATORS =====
// ============================================================================
// SHARED TECHNICAL INDICATORS - Universal Indicator Wrappers (SHARED MODULE)
// ============================================================================
// @version=6
// @description: Standard technical indicator wrappers with HTF support
//
// Purpose:
//   ✓ Consistent indicator calculation across all indicators
//   ✓ Higher Timeframe (HTF) support for all indicators
//   ✓ Reduced code duplication
//   ✓ Used by: CPM, ZZC, Pattern Pilot, Wave Analysis
//
// Categories:
//   ✓ Moving Averages (EMA, SMA, SMMA, WMA)
//   ✓ Oscillators (RSI, MACD, Stochastic, CCI, MFI)
//   ✓ Volatility (ATR, Bollinger Bands, Keltner Channels)
//   ✓ Trend (ADX, DMI, Parabolic SAR)
//   ✓ Volume (OBV, Volume MA, VWAP)
//
// Integration:
//   Reference in config.json: "../_shared/indicators.pine"
// ============================================================================

// ==== MOVING AVERAGES ====

// Exponential Moving Average
// @param length: Period length
// @returns EMA value
f_ema(int length) =>
    ta.ema(close, length)

// Simple Moving Average
// @param length: Period length
// @returns SMA value
f_sma(int length) =>
    ta.sma(close, length)

// Smoothed Moving Average (SMMA / RMA)
// @param length: Period length
// @returns SMMA value
f_smma(int length) =>
    ta.rma(close, length)

// Weighted Moving Average
// @param length: Period length
// @returns WMA value
f_wma(int length) =>
    ta.wma(close, length)

// ==== OSCILLATORS ====

// Relative Strength Index
// @param length: RSI period
// @returns RSI value (0-100)
f_rsi(int length) =>
    ta.rsi(close, length)

// MACD (Moving Average Convergence Divergence)
// @param fastLen: Fast EMA length
// @param slowLen: Slow EMA length
// @param signalLen: Signal line length
// @returns [macdLine, signalLine, histogram]
f_macd(int fastLen = 12, int slowLen = 26, int signalLen = 9) =>
    ta.macd(close, fastLen, slowLen, signalLen)

// MACD Histogram only
// @returns MACD histogram (macdLine - signalLine)
f_macd_hist() =>
    [m, s, _] = ta.macd(close, 12, 26, 9)
    m - s

// Stochastic Oscillator
// @param kLen: %K period
// @param kSmooth: %K smoothing
// @param dLen: %D period
// @returns [k, d]
f_stoch(int kLen = 14, int kSmooth = 1, int dLen = 3) =>
    ta.stoch(close, high, low, kLen)

// Stochastic RSI
// @param rsiLen: RSI period
// @param stochLen: Stochastic period
// @param kSmooth: %K smoothing
// @param dSmooth: %D smoothing
// @returns [k, d]
f_stochRSI(int rsiLen = 14, int stochLen = 14, int kSmooth = 3, int dSmooth = 3) =>
    float rsi = ta.rsi(close, rsiLen)
    float lowestRSI = ta.lowest(rsi, stochLen)
    float highestRSI = ta.highest(rsi, stochLen)
    float stochRSI = highestRSI - lowestRSI != 0 ? (rsi - lowestRSI) / (highestRSI - lowestRSI) * 100 : 0
    float k = ta.sma(stochRSI, kSmooth)
    float d = ta.sma(k, dSmooth)
    [k, d]

// Commodity Channel Index
// @param length: CCI period
// @returns CCI value
f_cci(int length = 20) =>
    ta.cci(close, length)

// Money Flow Index
// @param length: MFI period
// @returns MFI value (0-100)
f_mfi(int length = 14) =>
    ta.mfi(close, length)

// Rate of Change
// @param length: ROC period
// @returns ROC percentage
f_roc(int length = 9) =>
    ta.roc(close, length)

// ==== VOLATILITY INDICATORS ====

// Average True Range
// @param length: ATR period
// @param multiplier: ATR multiplier (default 1.0)
// @returns ATR value
f_atr(int length = 14, float multiplier = 1.0) =>
    ta.atr(length) * multiplier

// ATR as percentage of price
// @param length: ATR period
// @returns ATR percentage
f_atrPercent(int length = 14) =>
    ta.atr(length) / close * 100.0

// True Range as percentage
// @returns TR percentage
f_trPercent() =>
    ta.tr / close * 100.0

// Bollinger Bands
// @param length: BB period
// @param mult: Standard deviation multiplier
// @returns [upper, basis, lower]
f_bollinger(int length = 20, float mult = 2.0) =>
    float basis = ta.sma(close, length)
    float dev = ta.stdev(close, length)
    [basis + dev * mult, basis, basis - dev * mult]

// Keltner Channels
// @param length: EMA period
// @param atrLen: ATR period
// @param mult: ATR multiplier
// @returns [upper, basis, lower]
f_keltner(int length = 20, int atrLen = 10, float mult = 2.0) =>
    float basis = ta.ema(close, length)
    float atrVal = ta.atr(atrLen)
    [basis + atrVal * mult, basis, basis - atrVal * mult]

// Donchian Channels
// @param length: Period
// @returns [upper, basis, lower]
f_donchian(int length = 20) =>
    float upper = ta.highest(high, length)
    float lower = ta.lowest(low, length)
    float basis = (upper + lower) / 2.0
    [upper, basis, lower]

