// Pivot add + trim
f_add_pivot(float price, int idx, int dir) =>
    array.push(pivPrice, price)
    array.push(pivIndex, idx)
    array.push(pivDir, dir)
    array.push(pivTime, time)
    while array.size(pivPrice) > pivotsToKeep
        array.shift(pivPrice)
        array.shift(pivIndex)
        array.shift(pivDir)
        array.shift(pivTime)

// Compute swing metrics on new pivot
f_calc_swing_metrics() =>
    int size = array.size(pivPrice)
    if size >= 2
        float p1 = array.get(pivPrice, size - 2)
        float p2 = array.get(pivPrice, size - 1)
        int   i1 = array.get(pivIndex, size - 2)
        int   i2 = array.get(pivIndex, size - 1)
        float amp = math.abs(p2 - p1)
        int   bars = i2 - i1
        array.push(swingAmp, amp)
        array.push(swingBars, bars)
        float retrace = na
        float ext = na
        if size >= 3
            float p0 = array.get(pivPrice, size - 3)
            float prevSwing = math.abs(p1 - p0)
            retrace := prevSwing > 0 ? (amp / prevSwing) : na
            float prevAmp = array.size(swingAmp) >= 1 ? array.get(swingAmp, array.size(swingAmp) - 1) : na
            ext := na(prevAmp) or prevAmp == 0.0 ? na : amp / prevAmp
        array.push(swingRetrace, retrace)
        array.push(swingExt, ext)
        while array.size(swingAmp) > pivotsToKeep - 1
            array.shift(swingAmp)
            array.shift(swingBars)
            array.shift(swingRetrace)
            array.shift(swingExt)

// Draw ZigZag line last two pivots
f_draw_zigzag_line() =>
    if showZigZag and array.size(pivPrice) >= 2
        int size = array.size(pivPrice)
        float p1 = array.get(pivPrice, size - 2)
        float p2 = array.get(pivPrice, size - 1)
        int   i1 = array.get(pivIndex, size - 2)
        int   i2 = array.get(pivIndex, size - 1)
        int   d2 = array.get(pivDir,   size - 1)
        color lineColor = d2 > 0 ? colorUp : colorDown
        ln = line.new(i1, p1, i2, p2, xloc.bar_index, extend.none, lineColor, line.style_solid, 2)
        array.push(zigzagLines, ln)
        while array.size(zigzagLines) > 200
            line.delete(array.shift(zigzagLines))

// Safe getters with live data support
// IMPORTANT: These check if we're requesting the LATEST pivot (array size - 1)
// If so, and there's an unconfirmed extreme being tracked, use that live value
// This ensures visualizations track the moving pivot correctly during zoom/pan
f_get_pivot_price(int idx) =>
    if idx >= 0 and idx < array.size(pivPrice)
        // Check if this is the latest pivot AND we have a newer unconfirmed extreme
        isLatest = idx == array.size(pivPrice) - 1
        if isLatest and not na(lastExtreme) and not na(lastExtremeIdx)
            // Use live tracking value for latest pivot
            lastExtreme
        else
            array.get(pivPrice, idx)
    else
        na

f_get_pivot_dir(int idx) =>
    if idx >= 0 and idx < array.size(pivDir)
        isLatest = idx == array.size(pivDir) - 1
        if isLatest and currentDir != 0
            currentDir
        else
            array.get(pivDir, idx)
    else
        0

f_get_pivot_index(int idx) =>
    if idx >= 0 and idx < array.size(pivIndex)
        isLatest = idx == array.size(pivIndex) - 1
        if isLatest and not na(lastExtremeIdx)
            lastExtremeIdx
        else
            array.get(pivIndex, idx)
    else
        na

// Alternation check (H-L-H-L ...)
f_check_alternation(int startIdx, int count) =>
    bool valid = true
    if array.size(pivDir) >= startIdx + count
        for i = startIdx to startIdx + count - 2
            int d1 = array.get(pivDir, i)
            int d2 = array.get(pivDir, i + 1)
            if d1 * d2 > 0
                valid := false
                break
    else
        valid := false
    valid

// Overlap 1/4 forbidden for impulse
f_check_no_overlap(int startIdx) =>
    bool noOverlap = true
    if array.size(pivPrice) >= startIdx + 6
        float p1 = array.get(pivPrice, startIdx + 1)
        float p4 = array.get(pivPrice, startIdx + 4)
        int dir1 = array.get(pivDir, startIdx + 1)
        if dir1 > 0
            if p4 < p1
                noOverlap := false
        else
            if p4 > p1
                noOverlap := false
    else
        noOverlap := false
    noOverlap

// Fib helpers
f_in_fib_range(float actual, float target, float tol) =>
    float lower = target * (1.0 - tol)
    float upper = target * (1.0 + tol)
    actual >= lower and actual <= upper

// Time ratio check (bars duration)
f_check_time_ratios(int idx0, int idx1, int idx2, int idx3, int idx4, int idx5) =>
    int time1 = idx1 - idx0
    int time3 = idx3 - idx2
    int time5 = idx5 - idx4
    bool time3longest = time3 >= time1 and time3 >= time5
    float score = time3longest and time3 >= time1 * 1.2 ? 100.0 : (time3longest ? 80.0 : (time3 >= time1 * 0.8 ? 60.0 : 40.0))
    [score, time3longest]

// Momentum at bar
f_get_momentum_at_bar(int barIdx) =>
    int barsAgo = bar_index - barIdx
    float momentum = na
    if barsAgo >= 0
        if momentumType == "RSI"
            momentum := rsiSeries[barsAgo]
        else if momentumType == "MACD"
            momentum := macdHist[barsAgo]
    momentum

// Wave-3 momentum confirmation
f_check_wave3_momentum(int idx1, int idx3, string direction) =>
    float mom1 = f_get_momentum_at_bar(idx1)
    float mom3 = f_get_momentum_at_bar(idx3)
    float score = 70.0
    if not na(mom1) and not na(mom3)
        if direction == "UP"
            if momentumType == "RSI"
                score := (mom3 > mom1 and mom3 > 60) ? 100.0 : ((mom3 > mom1) ? 80.0 : 50.0)
            else if momentumType == "MACD"
                score := (mom3 > mom1 and mom3 > 0) ? 100.0 : ((mom3 > mom1) ? 80.0 : 50.0)
        else
            if momentumType == "RSI"
                score := (mom3 < mom1 and mom3 < 40) ? 100.0 : ((mom3 < mom1) ? 80.0 : 50.0)
            else if momentumType == "MACD"
                score := (mom3 < mom1 and mom3 < 0) ? 100.0 : ((mom3 < mom1) ? 80.0 : 50.0)
    [score, mom1, mom3]

// Volume confirmation (simplified)
f_check_volume_confirmation(int idx0, int idx1, int idx2, int idx3) =>
    float score = 70.0
    int bars1 = idx1 - idx0
    int bars3 = idx3 - idx2
    if bars1 > 0 and bars3 > 0
        int barsAgo1 = bar_index - idx1
        int barsAgo3 = bar_index - idx3
        if barsAgo1 >= 0 and barsAgo3 >= 0
            float vol1 = nz(volume[barsAgo1], 0)
            float vol3 = nz(volume[barsAgo3], 0)
            score := (vol1 > 0 and vol3 > vol1 * 1.2) ? 100.0 : ((vol3 > vol1) ? 80.0 : ((vol3 > vol1 * 0.8) ? 60.0 : 40.0))
    score

