// ENHANCED PROJECTION SYSTEM (Priority 3)
// ═════════════════════════════════════════════════════════════════════════════
// Multi-scenario wave projections with IF-THEN logic based on wave relationships

// Calculate wave projection targets (Min/Ideal/Max)
// Enhanced with multiple scenario detection for more accurate projections
f_calculate_wave_targets(string waveType, bool isUp, float p0, float p1, float p2, float p3, float p4) =>
    float minTarget = na
    float idealTarget = na
    float maxTarget = na

    if waveType == "WAVE_3"
        // ─────────────────────────────────────────────────────────────────────
        // WAVE 3 PROJECTION SCENARIOS
        // ─────────────────────────────────────────────────────────────────────
        // Wave 3 is typically the strongest wave:
        // - Minimum: 1.0 x Wave 1 (never shorter than Wave 1)
        // - Typical: 1.618 x Wave 1 (golden ratio)
        // - Extended: 2.618 x Wave 1 (strong trending markets)
        // ─────────────────────────────────────────────────────────────────────

        float wave1 = math.abs(p1 - p0)
        float wave2 = not na(p2) ? math.abs(p2 - p1) : na

        // Scenario 1: STANDARD IMPULSE (Wave 2 retraces 38.2%-61.8% of Wave 1)
        if not na(wave2) and wave2 / wave1 >= 0.382 and wave2 / wave1 <= 0.618
            minTarget := isUp ? p2 + (wave1 * 1.272) : p2 - (wave1 * 1.272)
            idealTarget := isUp ? p2 + (wave1 * 1.618) : p2 - (wave1 * 1.618)
            maxTarget := isUp ? p2 + (wave1 * 2.618) : p2 - (wave1 * 2.618)

        // Scenario 2: SHALLOW CORRECTION (Wave 2 < 38.2% → Strong trend → Extended Wave 3)
        else if not na(wave2) and wave2 / wave1 < 0.382
            minTarget := isUp ? p2 + (wave1 * 1.618) : p2 - (wave1 * 1.618)
            idealTarget := isUp ? p2 + (wave1 * 2.618) : p2 - (wave1 * 2.618)
            maxTarget := isUp ? p2 + (wave1 * 3.618) : p2 - (wave1 * 3.618)

        // Scenario 3: DEEP CORRECTION (Wave 2 > 61.8% → Weak trend → Shorter Wave 3)
        else if not na(wave2) and wave2 / wave1 > 0.618
            minTarget := isUp ? p2 + (wave1 * 1.0) : p2 - (wave1 * 1.0)
            idealTarget := isUp ? p2 + (wave1 * 1.272) : p2 - (wave1 * 1.272)
            maxTarget := isUp ? p2 + (wave1 * 1.618) : p2 - (wave1 * 1.618)

        // Scenario 4: FALLBACK (no Wave 2 data)
        else
            minTarget := isUp ? p2 + (wave1 * 1.0) : p2 - (wave1 * 1.0)
            idealTarget := isUp ? p2 + (wave1 * 1.618) : p2 - (wave1 * 1.618)
            maxTarget := isUp ? p2 + (wave1 * 2.618) : p2 - (wave1 * 2.618)

    else if waveType == "WAVE_5"
        // ─────────────────────────────────────────────────────────────────────
        // WAVE 5 PROJECTION SCENARIOS
        // ─────────────────────────────────────────────────────────────────────
        // Wave 5 projection depends on Wave 1 and Wave 3 relationship:
        // IF Wave 3 = Extended (> 1.618 x Wave 1)
        //    THEN Wave 5 = Short (0.618 x Wave 1)
        // IF Wave 3 = Normal (1.0-1.618 x Wave 1)
        //    THEN Wave 5 = Normal (0.618-1.0 x Wave 1)
        // IF Wave 3 = Short (< 1.0 x Wave 1) [INVALID but handle gracefully]
        //    THEN Wave 5 = Extended (1.0-1.618 x Wave 1)
        // ─────────────────────────────────────────────────────────────────────

        float wave1 = math.abs(p1 - p0)
        float wave3 = not na(p3) ? math.abs(p3 - p2) : na
        float wave4 = not na(p4) ? math.abs(p4 - p3) : na

        // Calculate Wave 3 extension ratio
        float wave3Ratio = not na(wave3) ? wave3 / wave1 : na

        // Scenario 1: WAVE 3 EXTENDED (> 1.618 x Wave 1 → Wave 5 will be shorter)
        if not na(wave3Ratio) and wave3Ratio > 1.618
            minTarget := isUp ? p4 + (wave1 * 0.382) : p4 - (wave1 * 0.382)
            idealTarget := isUp ? p4 + (wave1 * 0.618) : p4 - (wave1 * 0.618)
            maxTarget := isUp ? p4 + (wave1 * 1.0) : p4 - (wave1 * 1.0)

        // Scenario 2: WAVE 3 NORMAL (1.0-1.618 x Wave 1 → Wave 5 normal)
        else if not na(wave3Ratio) and wave3Ratio >= 1.0 and wave3Ratio <= 1.618
            minTarget := isUp ? p4 + (wave1 * 0.618) : p4 - (wave1 * 0.618)
            idealTarget := isUp ? p4 + (wave1 * 1.0) : p4 - (wave1 * 1.0)
            maxTarget := isUp ? p4 + (wave1 * 1.618) : p4 - (wave1 * 1.618)

        // Scenario 3: WAVE 3 SHORT (< 1.0 x Wave 1 → Wave 5 might extend)
        // Note: This violates Elliott Wave rules (Wave 3 can't be shortest)
        // But we handle it gracefully for incomplete patterns
        else if not na(wave3Ratio) and wave3Ratio < 1.0
            minTarget := isUp ? p4 + (wave1 * 1.0) : p4 - (wave1 * 1.0)
            idealTarget := isUp ? p4 + (wave1 * 1.618) : p4 - (wave1 * 1.618)
            maxTarget := isUp ? p4 + (wave1 * 2.618) : p4 - (wave1 * 2.618)

        // Scenario 4: ALTERNATIVE - Use 0.618 of Wave 1-3 total distance
        else if not na(p3)
            float totalDistance = math.abs(p3 - p0)
            minTarget := isUp ? p4 + (totalDistance * 0.382) : p4 - (totalDistance * 0.382)
            idealTarget := isUp ? p4 + (totalDistance * 0.618) : p4 - (totalDistance * 0.618)
            maxTarget := isUp ? p4 + (totalDistance * 1.0) : p4 - (totalDistance * 1.0)

        // Scenario 5: FALLBACK (minimal data)
        else
            minTarget := isUp ? p4 + (wave1 * 0.618) : p4 - (wave1 * 0.618)
            idealTarget := isUp ? p4 + (wave1 * 1.0) : p4 - (wave1 * 1.0)
            maxTarget := isUp ? p4 + (wave1 * 1.618) : p4 - (wave1 * 1.618)

    else if waveType == "WAVE_C"
        // ─────────────────────────────────────────────────────────────────────
        // WAVE C PROJECTION (Corrections)
        // ─────────────────────────────────────────────────────────────────────
        float waveA = math.abs(p1 - p0)
        float waveB = not na(p2) ? math.abs(p2 - p1) : na

        // Scenario 1: ZIGZAG (Wave B sharp correction ~50%)
        if not na(waveB) and waveB / waveA >= 0.382 and waveB / waveA <= 0.618
            minTarget := isUp ? p2 + (waveA * 1.0) : p2 - (waveA * 1.0)
            idealTarget := isUp ? p2 + (waveA * 1.272) : p2 - (waveA * 1.272)
            maxTarget := isUp ? p2 + (waveA * 1.618) : p2 - (waveA * 1.618)

        // Scenario 2: EXTENDED C (Wave B shallow)
        else if not na(waveB) and waveB / waveA < 0.382
            minTarget := isUp ? p2 + (waveA * 1.272) : p2 - (waveA * 1.272)
            idealTarget := isUp ? p2 + (waveA * 1.618) : p2 - (waveA * 1.618)
            maxTarget := isUp ? p2 + (waveA * 2.618) : p2 - (waveA * 2.618)

        // Scenario 3: FALLBACK
        else
            minTarget := isUp ? p2 + (waveA * 1.0) : p2 - (waveA * 1.0)
            idealTarget := isUp ? p2 + (waveA * 1.272) : p2 - (waveA * 1.272)
            maxTarget := isUp ? p2 + (waveA * 1.618) : p2 - (waveA * 1.618)

    [minTarget, idealTarget, maxTarget]

