// Returns human-readable scenario description for info display
f_get_projection_scenario(string waveType, float p0, float p1, float p2, float p3, float p4) =>
    string scenario = "Unknown"

    if waveType == "WAVE_3"
        float wave1 = math.abs(p1 - p0)
        float wave2 = not na(p2) ? math.abs(p2 - p1) : na

        if not na(wave2)
            float retrace = wave2 / wave1
            if retrace < 0.382
                scenario := "Shallow W2 → Extended W3"
            else if retrace >= 0.382 and retrace <= 0.618
                scenario := "Standard Impulse"
            else
                scenario := "Deep W2 → Short W3"
        else
            scenario := "Insufficient Data"

    else if waveType == "WAVE_5"
        float wave1 = math.abs(p1 - p0)
        float wave3 = not na(p3) ? math.abs(p3 - p2) : na

        if not na(wave3)
            float ratio = wave3 / wave1
            if ratio > 1.618
                scenario := "W3 Extended → Short W5"
            else if ratio >= 1.0 and ratio <= 1.618
                scenario := "W3 Normal → Normal W5"
            else if ratio < 1.0
                scenario := "W3 Short → Extended W5"
            else
                scenario := "Alternative: 0.618 Total"
        else
            scenario := "Insufficient Data"

    scenario

