// Scan for FLAT CORRECTION patterns (v2.0 Phase 2 - Priority 2)
f_detect_flat_patterns() =>
    int pc = array.size(pivPrice)
    if enablePatterns and enableFlats and pc >= minPivotsFor3
        int startLatest = pc - minPivotsFor3
        int startEarliest = math.max(0, startLatest - (windowsBack3 - 1))
        int span = startLatest - startEarliest
        if span >= 0
            for off = 0 to span
                int startIdx = startLatest - off
                float p0 = f_get_pivot_price(startIdx)
                float p1 = f_get_pivot_price(startIdx + 1)
                float p2 = f_get_pivot_price(startIdx + 2)
                float p3 = f_get_pivot_price(startIdx + 3)
                if na(p0) or na(p3)
                    continue

                // Check for Flat Correction
                [isFlat, flatType, flatConf, bRetrace, cVsA] = f_check_flat_correction(p0, p1, p2, p3)
                if isFlat
                    // Create pattern candidate with flat type
                    string patternName = flatType == "REGULAR" ? "REGULAR_FLAT" : (flatType == "EXPANDED" ? "EXPANDED_FLAT" : "RUNNING_FLAT")
                    c = PatternCandidate.new(patternName, startIdx, startIdx + 3, 4, true, "UNKNOWN", array.new_string(), flatConf, 100.0, 100.0, 0.0, 0.0, 70.0, 70.0)

                    // Check alternation
                    bool alternates = f_check_alternation(startIdx, 4)
                    if not alternates
                        array.push(c.violations, "No alternation")

                    // Add B retrace info
                    if bRetrace < 0.90 or bRetrace > 1.38
                        array.push(c.violations, str.format("B {0,number,#.##}% of A", bRetrace*100))

                    // Add C extension info
                    if flatType == "EXPANDED" and (cVsA < 1.10 or cVsA > 1.618)
                        array.push(c.violations, str.format("C {0,number,#.##}% of A", cVsA*100))
                    else if flatType == "RUNNING" and cVsA >= 1.10
                        array.push(c.violations, str.format("C {0,number,#.##}% (too long)", cVsA*100))

                    // Determine direction
                    int dir1 = f_get_pivot_dir(startIdx + 1)
                    c.direction := dir1 > 0 ? "UP" : "DOWN"

                    array.push(detectedPatterns, c)

